-- ============================================================================
-- Nexora catalog seed (generated from src/data/mockData.ts)
-- Safe to re-run: uses ON CONFLICT ... DO UPDATE.
-- ============================================================================

on conflict (id) do update set
  name = excluded.name, area = excluded.area, city = excluded.city,
  distance_km = excluded.distance_km, rating = excluded.rating,
  review_count = excluded.review_count, verified = excluded.verified,
  is_new = excluded.is_new, image = excluded.image, gallery = excluded.gallery,
  starting_price = excluded.starting_price, tags = excluded.tags,
  gender_category = excluded.gender_category, address = excluded.address,
  hours = excluded.hours, description = excluded.description;

on conflict (id) do update set
  name = excluded.name, duration_minutes = excluded.duration_minutes,
  price = excluded.price, category = excluded.category,
  description = excluded.description, sort_order = excluded.sort_order;

on conflict (id) do update set
  name = excluded.name, role = excluded.role, rating = excluded.rating,
  reviews_count = excluded.reviews_count, avatar = excluded.avatar,
  sort_order = excluded.sort_order;
